require __DIR__.'/../app/bootstrap.php';if(user())redirect('index.php');$error=null;
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$username=trim((string)($_POST['username']??''));$password=(string)($_POST['password']??'');$_SESSION['_login_attempts']=$_SESSION['_login_attempts']??[];$_SESSION['_login_attempts']=array_values(array_filter($_SESSION['_login_attempts'],fn($t)=>(time()-$t)<600));if(count($_SESSION['_login_attempts'])>=8){$error='تعداد تلاش‌های ورود بیش از حد مجاز است. چند دقیقه بعد دوباره تلاش کنید.';}else{$st=db()->prepare('SELECT u.*,r.name role,r.title role_title FROM users u JOIN roles r ON r.id=u.role_id WHERE u.username=? LIMIT 1');$st->execute([$username]);$u=$st->fetch();if($u&&(int)$u['is_active']===1&&password_verify($password,$u['password_hash'])){$_SESSION['_login_attempts']=[];session_regenerate_id(true);if(password_needs_rehash($u['password_hash'],PASSWORD_DEFAULT))db()->prepare('UPDATE users SET password_hash=? WHERE id=?')->execute([password_hash($password,PASSWORD_DEFAULT),$u['id']]);unset($u['password_hash']);$_SESSION['user']=$u;audit('login','user',(string)$u['id']);redirect('index.php');}$_SESSION['_login_attempts'][]=time();audit('login_failed','user',null,['username'=>$username]);$error='نام کاربری یا رمز عبور نادرست است.';}}
